package org.humanjourney.core.mapfeature;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import org.mockito.MockedStatic;
import net.minecraft.SharedConstants;
import net.minecraft.server.Bootstrap;
import net.minecraft.core.*;
import net.minecraft.core.registries.*;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.nbt.*;
import org.humanjourney.core.geography.GeographyRoles;
import org.humanjourney.core.water.WaterGeography.Point;
class FeatureProtocolTest {
 static MockedStatic<net.minecraftforge.fml.ModLoader> loader;static final UUID SESSION=new UUID(13,13);
 @BeforeAll static void bootstrap(){loader=mockStatic(net.minecraftforge.fml.ModLoader.class);loader.when(net.minecraftforge.fml.ModLoader::get).thenReturn(mock(net.minecraftforge.fml.ModLoader.class));SharedConstants.tryDetectVersion();Bootstrap.bootStrap();}
 @AfterAll static void close(){loader.close();}
 static RegistryFriendlyByteBuf buffer(){return new RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),RegistryAccess.fromRegistryOfRegistries(BuiltInRegistries.REGISTRY));}
 static FeaturePackets.Header h(long n){return new FeaturePackets.Header(SESSION,n,n,n);}
 static List<FeaturePackets.Frame> full(long n,Collection<MapFeature.View> views){return FeaturePackets.frames(h(n),FeaturePackets.Mode.FULL,0,views,List.of());}
 static void apply(ClientFeatureState c,List<FeaturePackets.Frame> frames){frames.forEach(c::accept);}
 static MapFeature.View view(String id){return FeatureModelTest.parse(FeatureModelTest.polygon(id,1)).view();}
 @Test void independentSavedDataRoundTripRetainsStaleIdsAndRevision(){var saved=new SavedFeatures();saved.discover(new GeographyRoles(true,true,false),FeatureModelTest.catalog(FeatureModelTest.line("river",1)),FeatureModelTest.DIM,50,54);saved.mark("stale");var tag=SavedFeatures.CODEC.encodeStart(NbtOps.INSTANCE,saved).getOrThrow();var copy=SavedFeatures.CODEC.parse(NbtOps.INSTANCE,tag).getOrThrow();assertEquals(saved.snapshot(),copy.snapshot());assertEquals(Set.of("river","stale"),copy.snapshot().ids());assertTrue(saved.isDirty());}
 @Test void packetProjectionCannotContainUndiscoveredNamesOrGeometry(){var data=FeatureModelTest.catalog(FeatureModelTest.polygon("known",1),FeatureModelTest.polygon("UNDISCOVERED_SECRET".toLowerCase(Locale.ROOT),99));var projected=FeatureCatalog.project(data,Set.of("known"));var b=buffer();try{var frame=full(1,projected.values()).getFirst();FeaturePackets.CODEC.encode(b,frame);String raw=b.toString(0,b.writerIndex(),java.nio.charset.StandardCharsets.UTF_8);assertFalse(raw.contains("undiscovered_secret"));assertFalse(raw.contains("discovery_radius"));assertEquals(frame,FeaturePackets.CODEC.decode(b));}finally{b.release();}}
 @Test void maximum512PointFeaturesFitBoundedNativePacket(){var points=new ArrayList<Point>();for(int i=0;i<512;i++){double a=2*Math.PI*i/512;points.add(new Point(Math.cos(a)*1000,Math.sin(a)*1000));}var views=new ArrayList<MapFeature.View>();for(int i=0;i<4;i++)views.add(new MapFeature.View("maximum_"+i,"Maximum "+i,MapFeature.Type.SEA,FeatureModelTest.DIM,i,new FeatureGeometry(FeatureGeometry.Kind.POLYGON,points,null)));var b=buffer();try{var frame=full(1,views).getFirst();FeaturePackets.CODEC.encode(b,frame);assertTrue(b.readableBytes()<FeaturePackets.MAX_BYTES);assertEquals(frame,FeaturePackets.CODEC.decode(b));}finally{b.release();}}
 @Test void multipartReplacementIsAtomicAndOutOfOrderPartsWork(){var c=new ClientFeatureState();apply(c,full(1,List.of(view("old"))));var many=new ArrayList<MapFeature.View>();for(int i=0;i<9;i++)many.add(view("area_"+i));var frames=full(2,many);assertEquals(3,frames.size());assertFalse(c.accept(frames.get(2)));assertFalse(c.accept(frames.get(0)));assertEquals(Set.of("old"),c.snapshot().features().keySet());assertTrue(c.accept(frames.get(1)));assertEquals(9,c.snapshot().count());}
 @Test void staleFramesAndCatalogRegressionsCannotReplaceNewState(){var c=new ClientFeatureState();apply(c,full(10,List.of(view("new"))));apply(c,full(1,List.of()));apply(c,FeaturePackets.frames(new FeaturePackets.Header(SESSION,11,11,1),FeaturePackets.Mode.FULL,0,List.of(),List.of()));assertEquals(Set.of("new"),c.snapshot().features().keySet());}
 @Test void deltaRequiresExactBaseAndDelayedPreResetStateCannotReturn(){var c=new ClientFeatureState();apply(c,full(1,List.of()));apply(c,FeaturePackets.frames(h(3),FeaturePackets.Mode.DELTA,2,List.of(view("second")),List.of()));assertTrue(c.needsResync());apply(c,FeaturePackets.frames(h(2),FeaturePackets.Mode.DELTA,1,List.of(view("first")),List.of()));assertEquals(2,c.snapshot().count());apply(c,FeaturePackets.frames(h(5),FeaturePackets.Mode.CLEAR,0,List.of(),List.of()));apply(c,full(4,List.of(view("old"))));assertEquals(0,c.snapshot().count());}
 @Test void roleRevocationHidesStateAndReconnectAcceptsFreshSession(){var c=new ClientFeatureState();apply(c,full(5,List.of(view("old"))));c.role(false);apply(c,full(6,List.of(view("hidden"))));assertEquals(0,c.snapshot().count());c.role(true);assertTrue(c.needsResync());var fresh=FeaturePackets.frames(new FeaturePackets.Header(UUID.randomUUID(),1,1,1),FeaturePackets.Mode.FULL,0,List.of(view("fresh")),List.of());apply(c,fresh);assertEquals(0,c.snapshot().count());c.clear();apply(c,fresh);assertEquals(Set.of("fresh"),c.snapshot().features().keySet());}
 @Test void malformedNativePayloadRetainsLastValidMirror(){var c=new ClientFeatureState();apply(c,full(1,List.of(view("valid"))));var b=buffer();try{b.writeZero(FeaturePackets.MAX_BYTES+1);var bad=FeaturePackets.CODEC.decode(b);assertFalse(bad.valid());assertFalse(c.accept(bad));assertEquals(Set.of("valid"),c.snapshot().features().keySet());b.clear();b.writeByte(0);assertFalse(FeaturePackets.CODEC.decode(b).valid());}finally{b.release();}}
 @Test void duplicateConflictingPartsDoNotPublishPartialState(){var c=new ClientFeatureState();var views=new ArrayList<MapFeature.View>();for(int i=0;i<5;i++)views.add(view("f_"+i));var frames=full(1,views);c.accept(frames.getFirst());c.accept(frames.getFirst());assertFalse(c.needsResync());assertFalse(c.accept(new FeaturePackets.Frame(h(1),FeaturePackets.Mode.FULL,0,0,2,List.of(),List.of(),null)));assertTrue(c.needsResync());assertEquals(0,c.snapshot().count());}
 @Test void changedAndRemovedFeaturesReplaceOnlyOnCompleteReloadSnapshot(){var c=new ClientFeatureState();apply(c,full(1,List.of(view("keep"),view("removed"))));var changed=FeatureModelTest.parse(FeatureModelTest.polygon("keep",10).replace("Label keep","New Label")).view();apply(c,full(2,List.of(changed)));assertEquals(Map.of("keep",changed),c.snapshot().features());}
 @Test void full2048FeatureTransferUses512BoundedParts(){var views=new ArrayList<MapFeature.View>();for(int i=0;i<2048;i++)views.add(view("feature_"+i));var parts=full(1,views);assertEquals(512,parts.size());assertTrue(parts.stream().allMatch(f->f.features().size()<=4));var c=new ClientFeatureState();apply(c,parts);assertEquals(2048,c.snapshot().count());}
 @Test void invalidFrameBoundsAndTrailingBytesAreRejected(){assertThrows(IllegalArgumentException.class,()->new FeaturePackets.Header(SESSION,0,0,0));assertThrows(IllegalArgumentException.class,()->new FeaturePackets.Frame(h(1),FeaturePackets.Mode.DELTA,1,0,1,List.of(),List.of(),null));var b=buffer();try{FeaturePackets.CODEC.encode(b,full(1,List.of()).getFirst());b.writeByte(9);assertFalse(FeaturePackets.CODEC.decode(b).valid());}finally{b.release();}}
}
